using NaughtyAttributes;
using Spine.Unity;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ButtonCustomEventSetup", menuName = "Data/BattleSceneSetups/Events/ButtonCustomEventSetup", order = 0)]
public class ButtonCustomEventSetup : CustomEventSetup
{
	public enum EventGlowColorType
	{
		BLUE,
		PURPLE,
		ORANGE,
		RED
	}

	public class EventGlowColor
	{
		public EventGlowColorType EventGlowColorType;

		public Color MinGlowColor;

		public Color MaxGlowColor;

		public EventGlowColor(EventGlowColorType EventGlowColorType, Color MinGlowColor, Color MaxGlowColor)
		{
			this.EventGlowColorType = EventGlowColorType;
			this.MinGlowColor = MinGlowColor;
			this.MaxGlowColor = MaxGlowColor;
		}

		public EventGlowColor(EventGlowColorType EventGlowColorType, Color MinGlowColor)
		{
			this.EventGlowColorType = EventGlowColorType;
			this.MinGlowColor = MinGlowColor;
		}
	}

	[Header("Event Button Data")]
	[SerializeField]
	private string eventID;

	[HorizontalLine(2f, EColor.Gray)]
	[Space(30f)]
	[Header("Event Sprite")]
	[SerializeField]
	private GameObject eventSpritesPrefab;

	[SerializeField]
	private bool enableAnimationSkeleton;

	[SerializeField]
	[ShowIf("enableAnimationSkeleton")]
	protected SkeletonDataAsset skeletonDataAsset;

	[SerializeField]
	private bool enableEventSprite;

	[SerializeField]
	[ShowIf("enableEventSprite")]
	private Sprite eventSprite;

	[HorizontalLine(2f, EColor.Gray)]
	[SerializeField]
	private bool enableCustomStartingAnimationName;

	[SerializeField]
	[ShowIf("enableCustomStartingAnimationName")]
	[SpineAnimation("", "skeletonDataAsset", true, false)]
	private string customStartingAnimationName;

	[SerializeField]
	private bool enableAfterStartingAnimationAnimationName;

	[SerializeField]
	[ShowIf("enableAfterStartingAnimationAnimationName")]
	[SpineAnimation("", "skeletonDataAsset", true, false)]
	private string afterStartingAnimationAnimationName;

	[HorizontalLine(2f, EColor.Gray)]
	[SerializeField]
	private bool enableCustomEventSpritesPosition;

	[SerializeField]
	[ShowIf("enableCustomEventSpritesPosition")]
	private Vector2 customEventSpritesPosition;

	[HorizontalLine(2f, EColor.Gray)]
	[Header("VFX")]
	[SerializeField]
	private EventGlowColorType eventGlowColorType;

	[SerializeField]
	private bool enableCustomGlowSize;

	[SerializeField]
	[ShowIf("enableCustomGlowSize")]
	private Vector2 customGlowSize;

	[SerializeField]
	private bool enableCustomGlowPosition;

	[SerializeField]
	[ShowIf("enableCustomGlowPosition")]
	private Vector2 customGlowPosition;

	[SerializeField]
	private bool enableCustomEffectsPrefab;

	[SerializeField]
	[ShowIf("enableCustomEffectsPrefab")]
	private GameObject customEffectsPrefab;

	[HorizontalLine(2f, EColor.Gray)]
	[Space(30f)]
	[Header("Text")]
	[SerializeField]
	private bool useSameEventDescriptionForAllButtons;

	[SerializeField]
	private bool anyOptionAppendStart;

	[SerializeField]
	private bool anyOptionAppendEnd;

	[HorizontalLine(2f, EColor.Gray)]
	[Space(30f)]
	[Header("Event Button Datas")]
	[SerializeField]
	protected EventButtonData[] eventButtonDatas;

	[Header("Localization")]
	[SerializeField]
	private bool enableRussianLanguageCustomEventTextSize;

	[SerializeField]
	[ShowIf("enableRussianLanguageCustomEventTextSize")]
	private float russianLanguageCustomEventTextSize;

	private EventGlowColor[] eventGlowColors = new EventGlowColor[4]
	{
		new EventGlowColor(EventGlowColorType.BLUE, new Color(0.1019608f, 0.4941176f, 83f / 85f, 0.6039216f)),
		new EventGlowColor(EventGlowColorType.PURPLE, new Color(0.6784314f, 0.2352941f, 81f / 85f, 0.6039216f)),
		new EventGlowColor(EventGlowColorType.ORANGE, new Color(1f, 0.509804f, 0.01960784f, 0.6039216f)),
		new EventGlowColor(EventGlowColorType.RED, new Color(0.7921569f, 0.04705882f, 0.2705882f, 0.6039216f))
	};

	public string EventName => ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(eventID + "_N");

	public string EventDescription => ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(eventID + "_D");

	public bool EnableCustomEventSpritesPosition => enableCustomEventSpritesPosition;

	public Vector2 CustomEventSpritesPosition => customEventSpritesPosition;

	public bool EnableCustomGlowSize => enableCustomGlowSize;

	public Vector2 CustomGlowSize => customGlowSize;

	public bool EnableCustomGlowPosition => enableCustomGlowPosition;

	public Vector2 CustomGlowPosition => customGlowPosition;

	public bool EnableRussianLanguageCustomEventTextSize => enableRussianLanguageCustomEventTextSize;

	public float RussianLanguageCustomEventTextSize => russianLanguageCustomEventTextSize;

	public GameObject SpawnEventSpritesGameObject(Transform eventSpriteGameObjectHolder)
	{
		GameObject gameObject = null;
		if (eventSpritesPrefab != null)
		{
			gameObject = ReferenceSingleton<PoolHandler>.Instance.GetObject(eventSpritesPrefab.name, eventSpriteGameObjectHolder);
			if (gameObject == null)
			{
				ReferenceSingleton<PoolHandler>.Instance.AddPool(eventSpritesPrefab);
				gameObject = ReferenceSingleton<PoolHandler>.Instance.GetObject(eventSpritesPrefab.name, eventSpriteGameObjectHolder);
			}
			if (enableAnimationSkeleton)
			{
				EventSpritesSkeleton component = gameObject.GetComponent<EventSpritesSkeleton>();
				component.Initialize(this, skeletonDataAsset, enableCustomStartingAnimationName ? customStartingAnimationName : "", enableAfterStartingAnimationAnimationName ? afterStartingAnimationAnimationName : "");
				InitializeSpineAnimation(component);
			}
			if (enableEventSprite)
			{
				gameObject.GetComponent<EventSpritesImage>().Initialize(eventSprite, this);
			}
			gameObject.GetComponent<EventSpritesGlow>().Initialize(GetEventGlowColor(), this);
			if (enableCustomEffectsPrefab)
			{
				Object.Instantiate(customEffectsPrefab, gameObject.transform);
			}
		}
		return gameObject;
	}

	private EventGlowColor GetEventGlowColor()
	{
		for (int i = 0; i < eventGlowColors.Length; i++)
		{
			if (eventGlowColors[i].EventGlowColorType == eventGlowColorType)
			{
				return eventGlowColors[i];
			}
		}
		return null;
	}

	protected virtual void InitializeSpineAnimation(EventSpritesSkeleton eventSpritesSkeleton)
	{
	}

	public virtual EventButtonData[] GetEventButtonDatas()
	{
		return eventButtonDatas;
	}

	public string GetEventButtonLoreDescriptionID(int buttonIndex)
	{
		return eventID + $"Option{buttonIndex + 1}Lore";
	}

	public string GetEventButtonLoreDescriptionSuccessID(int buttonIndex)
	{
		return eventID + $"Option{buttonIndex + 1}LoreSuccess";
	}

	public string GetEventButtonLoreDescriptionFailureID(int buttonIndex)
	{
		return eventID + $"Option{buttonIndex + 1}LoreFailure";
	}

	public string GetEventButtonResultDescriptionID(int buttonIndex)
	{
		return eventID + $"Option{buttonIndex + 1}Result";
	}

	public virtual string GetButtonPressedEventDescription(int buttonIndex)
	{
		string text = "";
		text = ((!useSameEventDescriptionForAllButtons) ? ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(eventID + $"Option{buttonIndex + 1}EventDescription") : ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(eventID + "AnyOptionEventDescription"));
		if (anyOptionAppendStart)
		{
			text = ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(eventID + "AnyOptionEventDescriptionAppendStart") + "\n" + text;
		}
		if (anyOptionAppendEnd)
		{
			text = text + "\n" + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(eventID + "AnyOptionEventDescriptionAppendEnd");
		}
		return text;
	}

	public virtual string GetButtonPressedEventDescriptionSuccess(int buttonIndex)
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(eventID + $"Option{buttonIndex + 1}EventDescriptionSuccess");
	}

	public virtual string GetButtonPressedEventDescriptionFailure(int buttonIndex)
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(eventID + $"Option{buttonIndex + 1}EventDescriptionFailure");
	}
}
